SET FOREIGN_KEY_CHECKS = 0;
SET NAMES utf8mb4;

CREATE TABLE `definition_achievement_levels` (
  `achievement_ref` int unsigned NOT NULL,
  `level` tinyint unsigned NOT NULL,
  `threshold` int unsigned NOT NULL,
  `badge_code` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL,
  `reward_activity_points` int unsigned NOT NULL DEFAULT '15',
  PRIMARY KEY (`achievement_ref`,`level`),
  UNIQUE KEY `uq_definition_achievement_levels_badge_code` (`badge_code`),
  CONSTRAINT `fk_definition_achievement_levels_achievement` FOREIGN KEY (`achievement_ref`) REFERENCES `definition_achievements` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `definition_achievements` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `code_base` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL,
  `max_level` tinyint unsigned NOT NULL,
  `enabled` tinyint(1) NOT NULL DEFAULT '1',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_definition_achievements_code_base` (`code_base`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `definition_catalog_club_gifts` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `offer_code` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL,
  `months_required` int unsigned NOT NULL,
  `ref_furni_def` int unsigned DEFAULT NULL,
  `product_type` enum('i','s','e') COLLATE utf8mb4_unicode_ci NOT NULL,
  `product_count` int NOT NULL DEFAULT '1',
  PRIMARY KEY (`id`),
  KEY `idx_definition_catalog_club_gifts_furni` (`ref_furni_def`),
  CONSTRAINT `fk_definition_catalog_club_gifts_furni` FOREIGN KEY (`ref_furni_def`) REFERENCES `definition_furniture` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `definition_catalog_marketplace_config` (
  `commission_percent` int unsigned NOT NULL DEFAULT '1',
  `token_batch_price` int unsigned NOT NULL DEFAULT '1',
  `token_batch_size` int unsigned NOT NULL DEFAULT '5',
  `offer_min_price` int unsigned NOT NULL DEFAULT '1',
  `offer_max_price` int unsigned NOT NULL DEFAULT '10000',
  `offer_expiration_hours` int unsigned NOT NULL DEFAULT '48',
  `average_price_period_days` int unsigned NOT NULL DEFAULT '7',
  `can_sell_whats_in_catalog` enum('0','1') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '1'
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `definition_catalog_page_body` (
  `ref_page_id` int NOT NULL,
  `layout_code` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL,
  `localization_images` json NOT NULL,
  `localization_texts` json NOT NULL,
  PRIMARY KEY (`ref_page_id`),
  CONSTRAINT `fk_definition_catalog_page_body_page` FOREIGN KEY (`ref_page_id`) REFERENCES `definition_catalog_page_header` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `definition_catalog_page_header` (
  `id` int NOT NULL AUTO_INCREMENT,
  `parent_id` int NOT NULL DEFAULT '-1',
  `color` int NOT NULL DEFAULT '0' COMMENT '0: light gray\r\n1: near-white gray\r\n2: golden yellow\r\n3: lime green\r\n4: lavender\r\n5: turquoise\r\n6: salmon orange\r\n7: yellow green\r\n8: pink/rose\r\n9: sky blue\r\n10: red\r\n11: medium gray',
  `icon` int NOT NULL DEFAULT '0',
  `display_name` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL,
  `coming_soon` tinyint(1) NOT NULL DEFAULT '0',
  `enabled` tinyint(1) NOT NULL DEFAULT '1',
  `min_rank` int NOT NULL DEFAULT '1',
  `order_num` int NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  KEY `idx_definition_catalog_pages_header_parent_id` (`parent_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `definition_catalog_page_offers` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `ref_page` int NOT NULL,
  `offer_code` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL,
  `price_credits` int NOT NULL DEFAULT '0',
  `price_activity_points` int NOT NULL DEFAULT '0',
  `club_only` tinyint(1) NOT NULL DEFAULT '0',
  `giftable` tinyint(1) NOT NULL DEFAULT '1',
  PRIMARY KEY (`id`),
  KEY `idx_definition_catalog_page_offers_ref_page` (`ref_page`),
  CONSTRAINT `fk_definition_catalog_page_offers_page` FOREIGN KEY (`ref_page`) REFERENCES `definition_catalog_page_header` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `definition_catalog_page_offers_products` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `ref_offer_id` int unsigned NOT NULL,
  `ref_furni_def` int unsigned DEFAULT NULL,
  `product_type` enum('i','s','e','h') COLLATE utf8mb4_unicode_ci NOT NULL,
  `product_extra_data` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `product_count` int NOT NULL DEFAULT '1',
  `product_rental_duration` int NOT NULL DEFAULT '-1',
  PRIMARY KEY (`id`),
  KEY `idx_definition_catalog_page_offers_products_offer` (`ref_offer_id`),
  KEY `idx_definition_catalog_page_offers_products_furni` (`ref_furni_def`),
  CONSTRAINT `fk_definition_catalog_page_offers_products_furni` FOREIGN KEY (`ref_furni_def`) REFERENCES `definition_furniture` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fk_definition_catalog_page_offers_products_offer` FOREIGN KEY (`ref_offer_id`) REFERENCES `definition_catalog_page_offers` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `definition_catalog_recycler_levels` (
  `level` tinyint unsigned NOT NULL,
  `odds` int unsigned NOT NULL,
  PRIMARY KEY (`level`),
  CONSTRAINT `chk_definition_catalog_recycler_levels_odds` CHECK ((`odds` >= 1))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `definition_catalog_recycler_prizes` (
  `level` tinyint unsigned NOT NULL,
  `ref_furni_def` int unsigned NOT NULL,
  PRIMARY KEY (`level`,`ref_furni_def`),
  KEY `idx_definition_catalog_recycler_prizes_furni` (`ref_furni_def`),
  CONSTRAINT `fk_definition_catalog_recycler_prizes_furni` FOREIGN KEY (`ref_furni_def`) REFERENCES `definition_furniture` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_definition_catalog_recycler_prizes_level` FOREIGN KEY (`level`) REFERENCES `definition_catalog_recycler_levels` (`level`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `definition_figure_colors` (
  `id` int unsigned NOT NULL,
  `palette_ref` int unsigned NOT NULL,
  `hex` char(6) COLLATE utf8mb4_unicode_ci NOT NULL,
  `club` tinyint unsigned NOT NULL DEFAULT '0',
  `selectable` tinyint unsigned NOT NULL DEFAULT '1',
  PRIMARY KEY (`id`),
  KEY `idx_figure_colors_palette` (`palette_ref`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `definition_figure_sets` (
  `id` int unsigned NOT NULL,
  `settype_ref` char(2) COLLATE utf8mb4_unicode_ci NOT NULL,
  `gender` char(1) COLLATE utf8mb4_unicode_ci NOT NULL,
  `club` tinyint unsigned NOT NULL DEFAULT '0',
  `colorable` tinyint unsigned NOT NULL DEFAULT '0',
  `selectable` tinyint unsigned NOT NULL DEFAULT '1',
  PRIMARY KEY (`id`),
  KEY `idx_figure_sets_settype` (`settype_ref`),
  CONSTRAINT `fk_figure_sets_settype` FOREIGN KEY (`settype_ref`) REFERENCES `definition_figure_settypes` (`type`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `definition_figure_settypes` (
  `type` char(2) COLLATE utf8mb4_unicode_ci NOT NULL,
  `palette_ref` int unsigned NOT NULL,
  `mandatory` tinyint unsigned NOT NULL DEFAULT '0',
  PRIMARY KEY (`type`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `definition_furniture` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `type` char(1) COLLATE utf8mb4_unicode_ci NOT NULL,
  `ref_furnidata` int unsigned NOT NULL,
  `classname` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL,
  `x_dim` int unsigned DEFAULT NULL,
  `y_dim` int unsigned DEFAULT NULL,
  `z_dim` decimal(6,4) DEFAULT NULL,
  `localization_name` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `localization_desc` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `logic_class` enum('basic','credit','dice','ecotron_box','habbowheel','hockey_score','jukebox','multistate','one_way_door','planet_system','present','randomstate','roomdimmer','sound_machine','stickie','trophy','window') COLLATE utf8mb4_unicode_ci NOT NULL,
  `visualization_class` enum('animated','bottle','gift_wrapped','habbowheel','party_beamer','planet_system','queue_tile','static','val_randomizer') COLLATE utf8mb4_unicode_ci NOT NULL,
  `interaction_logic` enum('none','toggle','teleport','vending','gate','roller','petfood','petnest','petwater','pettoy','pettreat','totem_leg','totem_head','totem_planet','hockey_light','sound_disk') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'none',
  `states` json DEFAULT NULL,
  `interaction_ids` json DEFAULT NULL,
  `is_sittable` tinyint(1) NOT NULL DEFAULT '0',
  `is_bed` tinyint(1) NOT NULL DEFAULT '0',
  `is_walkable` tinyint(1) NOT NULL DEFAULT '0',
  `is_stackable` tinyint(1) NOT NULL DEFAULT '0',
  `allow_trade` tinyint(1) NOT NULL DEFAULT '0',
  `allow_recycle` tinyint(1) NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_definition_furniture_classname` (`classname`),
  KEY `idx_definition_furniture_ref_furnidata` (`ref_furnidata`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `definition_furniture_aliases` (
  `furniture_classname` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL,
  `furniture_classname_alias` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL,
  `enabled` tinyint unsigned NOT NULL DEFAULT '1',
  PRIMARY KEY (`furniture_classname`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `definition_furniture_totem_config` (
  `leg_state` tinyint unsigned NOT NULL,
  `head_state` tinyint unsigned NOT NULL,
  `planet_state` tinyint unsigned NOT NULL,
  `effect_id` int unsigned NOT NULL,
  `effect_duration` int unsigned NOT NULL DEFAULT '172800',
  PRIMARY KEY (`leg_state`,`head_state`,`planet_state`),
  CONSTRAINT `chk_definition_furniture_totem_config_states` CHECK (((`leg_state` <= 11) and (`head_state` <= 14) and (`planet_state` <= 2) and (`effect_duration` > 0)))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `definition_fuse` (
  `label` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL,
  `requirement` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  PRIMARY KEY (`label`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `definition_gift_wrap_config` (
  `id` tinyint unsigned NOT NULL DEFAULT '1',
  `ref_furni_ids` json NOT NULL,
  `colour_array` json NOT NULL,
  `ribbon_array` json NOT NULL,
  `wrap_price_credits` int unsigned NOT NULL,
  PRIMARY KEY (`id`),
  CONSTRAINT `chk_gift_wrap_config_singleton` CHECK ((`id` = 1))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
CREATE TABLE `definition_help_faq_categories` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `name` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL,
  `description` text COLLATE utf8mb4_unicode_ci NOT NULL,
  `order_num` int NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `definition_help_faq_entries` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `category_ref` int unsigned NOT NULL,
  `question` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `answer` text COLLATE utf8mb4_unicode_ci NOT NULL,
  `front_page` enum('none','urgent','normal') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'none',
  `order_num` int NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  KEY `idx_definition_help_faq_entries_category` (`category_ref`),
  CONSTRAINT `fk_definition_help_faq_entries_category` FOREIGN KEY (`category_ref`) REFERENCES `definition_help_faq_categories` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `definition_interstitials` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `image_url` varchar(255) NOT NULL,
  `link` varchar(255) NOT NULL DEFAULT '',
  `active_from` datetime DEFAULT NULL,
  `active_until` datetime DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
CREATE TABLE `definition_moderation_presets` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `type` enum('user_message','room_message','offence') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `category` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Offences only, the group they are listed under.',
  `name` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT 'Offences only.',
  `message` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `order_num` int NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `definition_navigator_public_rooms` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `order_num` int NOT NULL DEFAULT '0',
  `image_size` enum('square','wide') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'square',
  `image` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `image_type` enum('internal','external') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'internal',
  `room_ref` int unsigned NOT NULL,
  `category_ref` int NOT NULL DEFAULT '-1',
  `club_only` tinyint(1) NOT NULL DEFAULT '0',
  `visible` enum('1','0') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '1',
  `nav_index` int NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  KEY `idx_definition_navigator_public_rooms_room_ref` (`room_ref`),
  KEY `idx_definition_navigator_public_rooms_category_ref` (`category_ref`),
  CONSTRAINT `fk_definition_navigator_public_rooms_room` FOREIGN KEY (`room_ref`) REFERENCES `rooms` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `definition_navigator_public_rooms_categories` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `order_num` int NOT NULL DEFAULT '0',
  `caption` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL,
  `image` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `definition_pet_breeds` (
  `pet_type` tinyint unsigned NOT NULL,
  `breed` tinyint unsigned NOT NULL,
  PRIMARY KEY (`pet_type`,`breed`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `definition_pet_colors` (
  `pet_type` tinyint unsigned NOT NULL,
  `color` char(6) COLLATE utf8mb4_unicode_ci NOT NULL,
  PRIMARY KEY (`pet_type`,`color`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `definition_pet_commands` (
  `id` tinyint unsigned NOT NULL,
  `name` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL,
  `required_level` tinyint unsigned NOT NULL,
  `experience` int unsigned NOT NULL DEFAULT '0',
  `energy_cost` int unsigned NOT NULL DEFAULT '0',
  `nutrition_cost` int unsigned NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_definition_pet_commands_name` (`name`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `definition_pet_food` (
  `furni_def_ref` int unsigned NOT NULL,
  `portions` tinyint unsigned NOT NULL,
  `full_state` tinyint unsigned NOT NULL DEFAULT '0',
  `nutrition` int unsigned NOT NULL DEFAULT '0',
  `energy` int unsigned NOT NULL DEFAULT '0',
  `experience` int unsigned NOT NULL DEFAULT '0',
  PRIMARY KEY (`furni_def_ref`),
  CONSTRAINT `fk_definition_pet_food_furni` FOREIGN KEY (`furni_def_ref`) REFERENCES `definition_furniture` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `definition_pet_levels` (
  `level` tinyint unsigned NOT NULL,
  `experience_cap` int unsigned NOT NULL,
  `nutrition_cap` int unsigned NOT NULL,
  `energy_cap` int unsigned NOT NULL,
  PRIMARY KEY (`level`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `definition_pet_speech` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `pet_type` tinyint unsigned NOT NULL,
  `speech_type` enum('random_speech','training_positive','training_negative','eating','playful','drinking','sleeping','welcome_home') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `text` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_definition_pet_speech_type` (`pet_type`,`speech_type`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `definition_public_room_exit_tiles` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `heightmap_ref` int unsigned NOT NULL,
  `x` int NOT NULL,
  `y` int NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_definition_public_room_exit_tiles_tile` (`heightmap_ref`,`x`,`y`),
  CONSTRAINT `fk_definition_public_room_exit_tiles_heightmap` FOREIGN KEY (`heightmap_ref`) REFERENCES `definition_room_heightmap` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `definition_public_room_furniture` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `classname` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL,
  `x_dim` int unsigned NOT NULL DEFAULT '1',
  `y_dim` int unsigned NOT NULL DEFAULT '1',
  `z_dim` decimal(6,4) NOT NULL DEFAULT '1.0000',
  `is_sittable` tinyint(1) NOT NULL DEFAULT '0',
  `is_bed` tinyint(1) NOT NULL DEFAULT '0',
  `is_walkable` tinyint(1) NOT NULL DEFAULT '0',
  `is_invisible` tinyint(1) NOT NULL DEFAULT '0',
  `extra1` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `extra2` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_definition_public_room_furniture_classname` (`classname`)
