  KEY `idx_definition_navigator_public_rooms_items_furni_ref` (`furni_ref`),
  KEY `idx_definition_navigator_public_rooms_items_heightmap_ref` (`heightmap_ref`),
  CONSTRAINT `fk_definition_navigator_public_rooms_items_furni` FOREIGN KEY (`furni_ref`) REFERENCES `definition_public_room_furniture` (`id`),
  CONSTRAINT `fk_definition_navigator_public_rooms_items_heightmap` FOREIGN KEY (`heightmap_ref`) REFERENCES `definition_room_heightmap` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `definition_public_room_libraries` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `heightmap_ref` int unsigned NOT NULL,
  `library_name` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `nav_code` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_definition_public_room_libraries_heightmap` (`heightmap_ref`),
  CONSTRAINT `fk_definition_public_room_libraries_heightmap` FOREIGN KEY (`heightmap_ref`) REFERENCES `definition_room_heightmap` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `definition_public_room_warp_tiles` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `heightmap_ref` int unsigned NOT NULL,
  `x` int NOT NULL,
  `y` int NOT NULL,
  `target_heightmap_ref` int unsigned NOT NULL,
  `target_x` int NOT NULL,
