  CONSTRAINT `fk_definition_public_room_warp_tiles_heightmap` FOREIGN KEY (`heightmap_ref`) REFERENCES `definition_room_heightmap` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_definition_public_room_warp_tiles_target` FOREIGN KEY (`target_heightmap_ref`) REFERENCES `definition_room_heightmap` (`id`) ON DELETE CASCADE
