CREATE TABLE `definition_room_ads` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `ref_room` int unsigned DEFAULT NULL,
  `image_url` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `link` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `enabled` enum('0','1') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '1',
  PRIMARY KEY (`id`),
  KEY `fk_definition_room_ads_room` (`ref_room`),
  CONSTRAINT `fk_definition_room_ads_room` FOREIGN KEY (`ref_room`) REFERENCES `rooms` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `definition_room_category` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `label` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL,
  `required_rights` tinyint unsigned NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_definition_room_category_label` (`label`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `definition_room_heightmap` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `label` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL,
  `heightmap` text COLLATE utf8mb4_unicode_ci NOT NULL,
  `club` tinyint(1) NOT NULL DEFAULT '0',
  `door_x` int NOT NULL,
  `door_y` int NOT NULL,
  `door_z` double NOT NULL,
  `door_dir` int NOT NULL DEFAULT '2',
  `max_step_height` decimal(4,2) DEFAULT NULL,
  `pool_water_max_height` decimal(4,2) DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_definition_room_heightmap_label` (`label`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `global_game_settings` (
  `private_rooms_limit` int unsigned NOT NULL DEFAULT '100',
  `max_favourite_rooms` int unsigned NOT NULL DEFAULT '50',
  `max_furniture_in_room` int unsigned NOT NULL DEFAULT '4000',
  `max_stickies_in_room` int unsigned NOT NULL DEFAULT '50',
  `max_queuetiles_in_room` int unsigned NOT NULL DEFAULT '100',
  `max_pets_in_room` int unsigned NOT NULL DEFAULT '5',
  `queuetile_furni_fusion_enabled` enum('0','1') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '0',
  `profanity_filter_enabled` tinyint(1) NOT NULL DEFAULT '1',
  `profanity_filter_replacement_word` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'bobba',
  `room_controllers_list_limit` int unsigned NOT NULL DEFAULT '25',
  `infobus_status` enum('closed','open') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'open',
  `infobus_room_ref` int unsigned DEFAULT NULL,
  `timezone` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'America/New_York',
  `happy_hour_windows` json NOT NULL DEFAULT (cast(_utf8mb4'{"weekday":{"start":"17:00","end":"18:00"},"weekend":{"start":"12:00","end":"13:00"}}' as json)),
  `recycler_status` enum('0','1') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '1',
  `recycler_cooldown` int unsigned NOT NULL DEFAULT '60',
  `recycler_prize_box_ref` int unsigned NOT NULL DEFAULT '1029',
  `trading_enabled` enum('0','1') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '1',
  `daily_respect_grant` int unsigned NOT NULL DEFAULT '3',
  `daily_pet_respect_grant` int unsigned NOT NULL DEFAULT '3',
  `marketplace_enabled` enum('0','1') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '1',
  `friends_limit` int unsigned NOT NULL DEFAULT '200',
  `friends_limit_club` int unsigned NOT NULL DEFAULT '600',
  `max_items_in_a_trade` int unsigned NOT NULL DEFAULT '100',
  `max_ignored_users` int unsigned NOT NULL DEFAULT '100',
  `room_events_enabled` enum('0','1') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '1',
  `room_ban_default_time` int unsigned NOT NULL DEFAULT '900',
  `room_idle_time_sleep` int unsigned NOT NULL DEFAULT '300',
  `room_idle_time_kick` int unsigned NOT NULL DEFAULT '900',
  `ban_default_hours` int unsigned NOT NULL DEFAULT '4',
  `superban_default_days` int unsigned NOT NULL DEFAULT '7',
  `ban_default_reason` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'Does not follow the Habbo Way.',
  `mute_default_hours` int unsigned NOT NULL DEFAULT '1',
  `room_mute_default_hours` int unsigned NOT NULL DEFAULT '1',
  `pets_enabled` enum('0','1') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '1',
  `pet_name_max_length` int unsigned NOT NULL DEFAULT '20',
  `pet_name_allowed_chars` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '^[A-Za-z0-9 À-ÖØ-öø-ɏḀ-ỿ_¡!#¿?|:.,;ƒ¬—ªº†»•‡‘¥µ-]+$',
  `pet_respect_min_account_days` int unsigned NOT NULL DEFAULT '3',
  `groups_limit` int unsigned NOT NULL DEFAULT '50',
  `groups_limit_club` int unsigned NOT NULL DEFAULT '100',
  `username_change_allowed` enum('0','1') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '1',
  `username_change_cooldown` int unsigned NOT NULL DEFAULT '14',
  `username_change_limit` int NOT NULL DEFAULT '5',
  `username_min_length` int unsigned NOT NULL DEFAULT '4',
  `username_max_length` int unsigned NOT NULL DEFAULT '15',
  `username_allowed_chars` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '^[a-zA-Z0-9.:;,_@!?-]+$',
  `max_guide_bots_in_hotel_at_once` int unsigned NOT NULL DEFAULT '10',
  KEY `fk_global_game_settings_infobus_room` (`infobus_room_ref`),
  KEY `fk_global_game_settings_recycler_prize_box` (`recycler_prize_box_ref`),
  CONSTRAINT `fk_global_game_settings_infobus_room` FOREIGN KEY (`infobus_room_ref`) REFERENCES `rooms` (`id`),
  CONSTRAINT `fk_global_game_settings_recycler_prize_box` FOREIGN KEY (`recycler_prize_box_ref`) REFERENCES `definition_furniture` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `global_historical_settings` (
  `catalogue_retention` int unsigned NOT NULL DEFAULT '30',
  `chatlogs_rooms_retention` int unsigned NOT NULL DEFAULT '21',
  `chatlogs_im_retention` int unsigned NOT NULL DEFAULT '30',
  `trading_retention` int unsigned NOT NULL DEFAULT '60',
  `room_visits_retention` int unsigned NOT NULL DEFAULT '30',
  `moderation_actions_retention` int unsigned NOT NULL DEFAULT '0',
  `marketplace_sales_retention` int unsigned NOT NULL DEFAULT '90'
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `global_message_texts` (
  `message_key` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL,
  `message_text` text COLLATE utf8mb4_unicode_ci NOT NULL,
  PRIMARY KEY (`message_key`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `global_profanity_words` (
  `word` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL,
  PRIMARY KEY (`word`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `global_reward_settings` (
  `rewards_enabled` enum('0','1') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '1',
  `credit_reward_interval` int NOT NULL DEFAULT '60',
  `credit_reward_amount` int NOT NULL DEFAULT '25',
  `pixel_reward_interval` int NOT NULL DEFAULT '13',
  `pixel_reward_amount` int NOT NULL DEFAULT '5'
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `groups` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `ref_owner` int unsigned NOT NULL,
  `name` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL,
  `description` text COLLATE utf8mb4_unicode_ci NOT NULL,
  `badge` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'b05030s05013s05015s09004',
  `ref_room` int unsigned DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT (utc_timestamp()),
  `is_private` enum('0','1') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  KEY `fk_groups_owner` (`ref_owner`),
  KEY `fk_groups_room` (`ref_room`),
  CONSTRAINT `fk_groups_owner` FOREIGN KEY (`ref_owner`) REFERENCES `users` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_groups_room` FOREIGN KEY (`ref_room`) REFERENCES `rooms` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `groups_join_requests` (
  `ref_group` int unsigned NOT NULL,
  `ref_user` int unsigned NOT NULL,
  `requested_at` datetime NOT NULL DEFAULT (utc_timestamp()),
  PRIMARY KEY (`ref_group`,`ref_user`),
  KEY `fk_groups_join_requests_user` (`ref_user`),
  CONSTRAINT `fk_groups_join_requests_group` FOREIGN KEY (`ref_group`) REFERENCES `groups` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_groups_join_requests_user` FOREIGN KEY (`ref_user`) REFERENCES `users` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `groups_tags` (
  `ref_group` int unsigned NOT NULL,
  `tag` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL,
  PRIMARY KEY (`ref_group`,`tag`),
  CONSTRAINT `fk_groups_tags_group` FOREIGN KEY (`ref_group`) REFERENCES `groups` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `guide_bot_actions` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `trigger_type` enum('user_says','user_shouts','user_chats','on_arrival','do_at_random') COLLATE utf8mb4_unicode_ci NOT NULL,
  `trigger_data` json DEFAULT NULL,
  `responses` json NOT NULL,
  `tile_distance_required` int unsigned NOT NULL DEFAULT '0' COMMENT '0 means that any distance from the trigger (if applicable) will cause the response.',
  `enabled` enum('0','1') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '1',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `guide_bot_data` (
  `bot_name` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'Guide Bot',
  `bot_gender` enum('M','F') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'F',
  `bot_figure` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'hr-836-61.sh-730-110.lg-695-110.ch-824-110.hd-600-2.he-1607',
  `bot_motto` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'Here to help for 24 hours!'
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `historical_catalog_purchases` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `purchased_at` datetime(3) NOT NULL,
  `user_ref` int unsigned NOT NULL,
  `page_ref` int unsigned NOT NULL,
  `offer_ref` int unsigned NOT NULL,
  `credits` int unsigned NOT NULL,
  `activity_points` int unsigned NOT NULL,
  `gift_receiver_ref` int unsigned DEFAULT NULL,
  `ip_address` varchar(45) COLLATE utf8mb4_unicode_ci NOT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_historical_catalog_purchases_at` (`purchased_at`),
  KEY `idx_historical_catalog_purchases_user` (`user_ref`,`purchased_at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `historical_chatlogs_im` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `sent_at` datetime(3) NOT NULL,
  `from_user_ref` int unsigned NOT NULL,
  `to_user_ref` int unsigned NOT NULL,
  `message` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `ip_address` varchar(45) COLLATE utf8mb4_unicode_ci NOT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_historical_chatlogs_im_at` (`sent_at`),
  KEY `idx_historical_chatlogs_im_from` (`from_user_ref`,`sent_at`),
  KEY `idx_historical_chatlogs_im_to` (`to_user_ref`,`sent_at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `historical_chatlogs_rooms` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `said_at` datetime(3) NOT NULL,
  `user_ref` int unsigned NOT NULL,
  `room_ref` int unsigned NOT NULL,
  `message` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `type` enum('chat','shout','whisper') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `whispered_user_ref` int unsigned DEFAULT NULL,
  `ip_address` varchar(45) COLLATE utf8mb4_unicode_ci NOT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_historical_chatlogs_rooms_at` (`said_at`),
  KEY `idx_historical_chatlogs_rooms_room` (`room_ref`,`said_at`),
  KEY `idx_historical_chatlogs_rooms_user` (`user_ref`,`said_at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `historical_marketplace_sales` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `sold_at` datetime NOT NULL,
  `offer_ref` int unsigned NOT NULL,
  `item_ref` int unsigned NOT NULL,
  `furni_def_ref` int unsigned NOT NULL,
  `seller_ref` int unsigned NOT NULL,
  `buyer_ref` int unsigned NOT NULL,
  `asking_price` int unsigned NOT NULL,
  `price` int unsigned NOT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_historical_marketplace_sales_furni` (`furni_def_ref`,`sold_at`),
  KEY `idx_historical_marketplace_sales_at` (`sold_at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `historical_moderation_actions` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `performed_at` datetime NOT NULL,
  `moderator_ref` int unsigned DEFAULT NULL,
  `user_ref` int unsigned DEFAULT NULL,
  `room_ref` int unsigned DEFAULT NULL,
  `action` enum('caution','message','kick','ban','room_caution','room_message','room_lock','room_rename','room_kick') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `message` varchar(500) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `issue_message` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'The call for help it was done from, if any.',
  PRIMARY KEY (`id`),
  KEY `idx_historical_moderation_actions_user` (`user_ref`,`action`),
  KEY `idx_historical_moderation_actions_performed` (`performed_at`),
  KEY `fk_historical_moderation_actions_moderator` (`moderator_ref`),
  KEY `fk_historical_moderation_actions_room` (`room_ref`),
  CONSTRAINT `fk_historical_moderation_actions_moderator` FOREIGN KEY (`moderator_ref`) REFERENCES `users` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fk_historical_moderation_actions_room` FOREIGN KEY (`room_ref`) REFERENCES `rooms` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fk_historical_moderation_actions_user` FOREIGN KEY (`user_ref`) REFERENCES `users` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `historical_room_visits` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `user_ref` int unsigned NOT NULL,
  `room_ref` int unsigned NOT NULL,
  `entered_at` datetime(3) NOT NULL,
  `left_at` datetime(3) NOT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_historical_room_visits_user` (`user_ref`,`entered_at`),
  KEY `idx_historical_room_visits_entered` (`entered_at`),
  KEY `fk_historical_room_visits_room` (`room_ref`),
  CONSTRAINT `fk_historical_room_visits_room` FOREIGN KEY (`room_ref`) REFERENCES `rooms` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_historical_room_visits_user` FOREIGN KEY (`user_ref`) REFERENCES `users` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `historical_trading` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `completed_at` datetime NOT NULL,
  `room_ref` int unsigned NOT NULL,
  `user1_ref` int unsigned NOT NULL,
  `user1_ip` varchar(45) COLLATE utf8mb4_unicode_ci NOT NULL,
  `user2_ref` int unsigned NOT NULL,
  `user2_ip` varchar(45) COLLATE utf8mb4_unicode_ci NOT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_historical_trading_user1` (`user1_ref`,`completed_at`),
  KEY `idx_historical_trading_user2` (`user2_ref`,`completed_at`),
  KEY `idx_historical_trading_at` (`completed_at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `historical_trading_items` (
  `trade_ref` int unsigned NOT NULL,
  `item_ref` int unsigned NOT NULL,
  `from_user_ref` int unsigned NOT NULL,
  `furni_def_ref` int unsigned NOT NULL,
  `extra_data` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  PRIMARY KEY (`trade_ref`,`item_ref`),
  KEY `idx_historical_trading_items_item` (`item_ref`),
  CONSTRAINT `fk_historical_trading_items_trade` FOREIGN KEY (`trade_ref`) REFERENCES `historical_trading` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `historical_username_changes` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `ref_user` int unsigned NOT NULL,
  `old_username` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL,
  `new_username` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL,
  `changed_at` datetime NOT NULL DEFAULT (utc_timestamp()),
  PRIMARY KEY (`id`),
  KEY `idx_historical_username_changes_user` (`ref_user`,`changed_at`),
  KEY `idx_historical_username_changes_old` (`old_username`),
  CONSTRAINT `fk_historical_username_changes_user` FOREIGN KEY (`ref_user`) REFERENCES `users` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `marketplace_offers` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `item_ref` int unsigned DEFAULT NULL,
  `seller_ref` int unsigned NOT NULL,
  `furni_def_ref` int unsigned NOT NULL,
  `asking_price` int unsigned NOT NULL,
  `price` int unsigned NOT NULL,
  `state` enum('open','sold') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'open',
  `created_at` datetime NOT NULL DEFAULT (utc_timestamp()),
  `expires_at` datetime NOT NULL,
  `sold_at` datetime DEFAULT NULL,
  `buyer_ref` int unsigned DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_marketplace_offers_item` (`item_ref`),
  KEY `idx_marketplace_offers_cheapest` (`state`,`furni_def_ref`,`price`),
  KEY `idx_marketplace_offers_seller` (`seller_ref`,`state`),
  KEY `fk_marketplace_offers_furni` (`furni_def_ref`),
  KEY `fk_marketplace_offers_buyer` (`buyer_ref`),
  CONSTRAINT `fk_marketplace_offers_buyer` FOREIGN KEY (`buyer_ref`) REFERENCES `users` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fk_marketplace_offers_furni` FOREIGN KEY (`furni_def_ref`) REFERENCES `definition_furniture` (`id`),
  CONSTRAINT `fk_marketplace_offers_item` FOREIGN KEY (`item_ref`) REFERENCES `users_items` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_marketplace_offers_seller` FOREIGN KEY (`seller_ref`) REFERENCES `users` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `moderation_issues` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `state` enum('open','picked','closed') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'open',
  `category` smallint unsigned NOT NULL COMMENT '101 sexual, 102 personal information, 103 scam, 104 bullying, 105 disruption, 106 other',
  `reporter_ref` int unsigned NOT NULL,
  `reported_ref` int unsigned DEFAULT NULL,
  `room_ref` int unsigned DEFAULT NULL,
  `message` varchar(500) COLLATE utf8mb4_unicode_ci NOT NULL,
  `picker_ref` int unsigned DEFAULT NULL,
  `resolution` enum('useless','abusive','resolved') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `created_at` datetime NOT NULL,
  `picked_at` datetime DEFAULT NULL,
  `closed_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_moderation_issues_state` (`state`),
  KEY `idx_moderation_issues_reporter` (`reporter_ref`),
  KEY `idx_moderation_issues_reported` (`reported_ref`),
  KEY `fk_moderation_issues_room` (`room_ref`),
  KEY `fk_moderation_issues_picker` (`picker_ref`),
  CONSTRAINT `fk_moderation_issues_picker` FOREIGN KEY (`picker_ref`) REFERENCES `users` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fk_moderation_issues_reported` FOREIGN KEY (`reported_ref`) REFERENCES `users` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fk_moderation_issues_reporter` FOREIGN KEY (`reporter_ref`) REFERENCES `users` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_moderation_issues_room` FOREIGN KEY (`room_ref`) REFERENCES `rooms` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `polls` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `ref_room` int unsigned NOT NULL,
  `name` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL,
  `thanks_message` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'Thank you for answering the poll!',
  `type` enum('survey','quiz') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'survey',
  `reward_type` enum('none','furni','badge') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'none',
  `reward` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `enabled` enum('0','1') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '1',
  PRIMARY KEY (`id`),
  KEY `fk_polls_room` (`ref_room`),
  CONSTRAINT `fk_polls_room` FOREIGN KEY (`ref_room`) REFERENCES `rooms` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `polls_question_options` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `ref_question` int unsigned NOT NULL,
  `number` int unsigned NOT NULL,
  `content` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `is_correct` enum('0','1') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_polls_question_options_number` (`ref_question`,`number`),
  CONSTRAINT `fk_polls_question_options_question` FOREIGN KEY (`ref_question`) REFERENCES `polls_questions` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `polls_questions` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `ref_poll` int unsigned NOT NULL,
  `number` int unsigned NOT NULL,
  `type` enum('single','multiple','text') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'single',
  `content` varchar(500) COLLATE utf8mb4_unicode_ci NOT NULL,
  `selection_min` int unsigned NOT NULL DEFAULT '1',
  `selection_max` int unsigned NOT NULL DEFAULT '1',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_polls_questions_number` (`ref_poll`,`number`),
  CONSTRAINT `fk_polls_questions_poll` FOREIGN KEY (`ref_poll`) REFERENCES `polls` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `room_bots` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `room_ref` int unsigned NOT NULL,
  `user_ref` int unsigned DEFAULT NULL COMMENT 'For now NULL: users owning bots is not compatible with V48.',
  `name` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL,
  `gender` enum('M','F') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'M' COMMENT 'Not sent in V48: the client draws every bot as M.',
  `figure` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `motto` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `x` int NOT NULL,
  `y` int NOT NULL,
  `z` decimal(6,4) NOT NULL DEFAULT '0.0000',
  `rotation` int NOT NULL DEFAULT '2' COMMENT '0-7, 0 = north, clockwise.',
  `walkable_area` json DEFAULT NULL COMMENT 'Where it may walk: tiles [x, y] and inclusive rectangles [x1, y1, x2, y2]. NULL: any walkable tile but the door.',
  `diagonal_move_allowed` enum('0','1') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '1',
  `created_at` datetime NOT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_room_bots_room_ref` (`room_ref`),
  KEY `fk_room_bots_user` (`user_ref`),
  CONSTRAINT `fk_room_bots_room` FOREIGN KEY (`room_ref`) REFERENCES `rooms` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_room_bots_user` FOREIGN KEY (`user_ref`) REFERENCES `users` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `room_bots_actions` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `bot_ref` int unsigned NOT NULL,
  `trigger_type` enum('user_says','user_shouts','do_at_random') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `trigger_data` json DEFAULT NULL,
  `responses` json NOT NULL,
  `tile_distance_required` int unsigned NOT NULL DEFAULT '0' COMMENT '0 means that any distance from the trigger (if applicable) will cause the response.',
