  `ref_item2` int unsigned NOT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_users_teleport_pairs_ref_item1` (`ref_item1`),
  KEY `idx_users_teleport_pairs_ref_item2` (`ref_item2`),
  CONSTRAINT `fk_users_teleport_pairs_item1` FOREIGN KEY (`ref_item1`) REFERENCES `users_items` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_users_teleport_pairs_item2` FOREIGN KEY (`ref_item2`) REFERENCES `users_items` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `users_token` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `user_id` int unsigned NOT NULL,
  `token` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL,
  `created_at` datetime NOT NULL DEFAULT (utc_timestamp()),
  `expires_at` datetime NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_users_token_token` (`token`),
  KEY `idx_users_token_user_id` (`user_id`),
  CONSTRAINT `fk_users_token_user` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `users_visited_rooms` (
  `user_ref` int unsigned NOT NULL,
  `room_ref` int unsigned NOT NULL,
  `first_visited_at` datetime NOT NULL DEFAULT (utc_timestamp()),
  `last_visited_at` datetime NOT NULL,
  PRIMARY KEY (`user_ref`,`room_ref`),
  KEY `fk_users_visited_rooms_room` (`room_ref`),
  KEY `idx_users_visited_rooms_last_visited` (`user_ref`,`last_visited_at`),
  CONSTRAINT `fk_users_visited_rooms_room` FOREIGN KEY (`room_ref`) REFERENCES `rooms` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_users_visited_rooms_user` FOREIGN KEY (`user_ref`) REFERENCES `users` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `users_voted_rooms` (
  `user_ref` int unsigned NOT NULL,
  `room_ref` int unsigned NOT NULL,
  `vote` tinyint NOT NULL,
  PRIMARY KEY (`user_ref`,`room_ref`),
  KEY `idx_users_voted_rooms_room_ref` (`room_ref`),
  CONSTRAINT `fk_users_voted_rooms_room` FOREIGN KEY (`room_ref`) REFERENCES `rooms` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_users_voted_rooms_user` FOREIGN KEY (`user_ref`) REFERENCES `users` (`id`) ON DELETE CASCADE,
  CONSTRAINT `chk_users_voted_rooms_vote` CHECK ((`vote` in (-(1),1)))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `users_wardrobe` (
  `user_ref` int unsigned NOT NULL,
  `slot` tinyint unsigned NOT NULL,
  `figure` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `gender` enum('M','F') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  PRIMARY KEY (`user_ref`,`slot`),
  CONSTRAINT `fk_users_wardrobe_user` FOREIGN KEY (`user_ref`) REFERENCES `users` (`id`) ON DELETE CASCADE,
  CONSTRAINT `chk_users_wardrobe_slot` CHECK ((`slot` between 1 and 10))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `voucher_codes` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `hash_code` char(64) COLLATE utf8mb4_unicode_ci NOT NULL,
  `redeemable_type` enum('credit','furni','club') COLLATE utf8mb4_unicode_ci NOT NULL,
  `redeemable_data` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `active` tinyint unsigned NOT NULL DEFAULT '0',
  `activated_date` datetime DEFAULT NULL,
  `redeemed_date` datetime DEFAULT NULL,
  `redeemed_user_ref` int unsigned DEFAULT NULL,
  `redeemed_user_ip` varchar(45) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_voucher_codes_hash_code` (`hash_code`),
  KEY `idx_voucher_codes_redeemed_user_ref` (`redeemed_user_ref`),
  CONSTRAINT `fk_voucher_codes_redeemed_user` FOREIGN KEY (`redeemed_user_ref`) REFERENCES `users` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

