INSERT INTO `definition_catalog_marketplace_config` VALUES (1,1,5,1,10000,48,7,'1');
INSERT INTO `definition_catalog_page_body` VALUES (1,'frontpage3','[\"catalog_frontpage_headline2_en\", \"shabbolin_300x187_E\", \"\"]','[\"Welcome to Dragon Hotel!\", \"There\'s a new Rare waiting in the catalog for you...\", \"Take me there!\", \"What is Dragon Hotel? \", \"I\'m glad you asked! I made Dragon Hotel as a way to reminisce my memories as a teenager playing Habbo mostly through 2007-2010.\\nV48 is the last version before major changes arrived (e.g. VIP club, Battle Banzai, Wired, etc.).\\nI will try to add all features that were available back (and maybe add some new ones!)\", \"Redeem a voucher code here:\", \"Rares\", \"#fff4d9\", \"#fff4d9\", \"Great, now take me to the HC Page>>\", \"Buy Habbo Club\"]'),(4,'default_3x3','[\"catalog_bank_headline1\", \"catalog_bank_teaser\", \"catalog_special_txtbg1\"]','[\"Exchange your Habbo Credits into tradeable Credits. Then you are able to use Credits in a Trade for Furni!\", \"Click on an item to see more details\", \"Refundable goods!\"]'),(12,'default_3x3','[\"catalog_rares_headline1\", \"catalog_cltbs_teaser_en\"]','[\"Every Rare here is a piece of history - available for a short time, then gone for good. Grab one while you can, before it becomes a story you tell newer Habbos about.\", \"\", \"\"]'),(25,'spaces','[\"look_feel\"]','[\"Floors, wallpapers and landscapes - get a groovy combination for your room! Use our sample room below to try before you buy! Select your favourite designs and colours and simply click Buy!\"]'),(31,'pixelrent','[\"catalog_pixelrent_headline1_en\", \"catalog_pxl_teaser3_en\"]','[\"Hire some cool effects to add an explosive touch to your room. From bubbles to firestarters, you can enhance your room dramatically!\"]'),(32,'pixeleffects','[\"catalog_pixeleffects_headline1_en\", \"catalog_pxl_teaser1_en\"]','[\"Tune your character with cool effects that fit the occasion. Do you want to fly away with the red carpet or be in the spotlight? Now is your chance!\"]'),(33,'default_3x3','[\"catalog_hello_header1_en\", \"catalog_hello_teaser1_en\"]','[\"Hello Furni is available with Pixels and is perfect if you are decorating your room for the very first time. The Furni is yours to keep and therefore cannot be traded.\", \"Click on an item for details.\"]'),(34,'default_3x3','[\"catalog_automobile_header1_en\", \"catalog_automobile_teaser1_en\"]','[\"Every Habbo needs a car effect! Not only do they bring a bit of the outside inside, they also enhance the air quality! And what better gift for a friend than a beautiful traffic sign or elegant pile of tires...\"]'),(51,'recycler','[\"catalog_recycler_headline3\", \"ctlg_ecotron_image\"]','[\"Drag 5 items to the boxes below and click recycle. Recyclable items display a recyclable tag in your inventory. Check out the prizes and the instructions for recycling before you recycle.\"]'),(52,'recycler_prizes','[\"catalog_recycler_headline3\"]','[\"What are the prizes? Ecotron box may contain one of these:\"]'),(53,'recycler_info','[\"catalog_recycler_headline3\", \"ctlg_ecotron_box\"]','[\"The Ecotron is a furni recycler. Get rid of old furni... what will you get in return? It\'s a surprise! Become a Habbo eco-warrior. No refunds!\", \"How to use the Ecotron?\", \"1. Just drag 5 items from your inventory to the Ecotron. One item / square. Recyclable items are marked in your inventory with an image. When you have 5 items in the boxes, click the \\\"Recycle\\\" button. You can now find the Ecotron prize box from your inventory.\\r\\n2. Click the box to  see its tag. Open the box, or trade it unopened. The timer shows you how long you have to wait before you can recycle more items. Check the prizes before you recycle - don\'t be surprised by the surprise!\", \"\"]'),(61,'pets','[\"catalog_pet_headline1_en\"]','[\"Wet noses, paws, yaps and woofs! You\'re about to enter the world of Habbo Dogs. An adorable and faithful servant awaits you with a wagging tail everytime they see you. Find a new friend from our ever-changing selection.\", \"Name your Dog:\", \"Pick a color:\", \"Pick a breed:\"]'),(62,'pets','[\"catalog_pet_headline1_en\"]','[\"Fluff, whiskers, meows and purrs! You\'re about to enter the world of Habbo Cats. These cute little critters will keep you company if you look after them well. Find a new friend from our ever-changing selection.\", \"Name your Cat:\", \"Pick a color:\", \"Pick a breed:\"]'),(63,'pets','[\"catalog_pet_headline1_en\"]','[\"Scaly skin, growls and snaps! You\'re about to enter the world of Habbo Crocs. Security for your room or to scare your friends a trustworthy and surprisingly loving companion can be yours. Find a new friend from our ever-changing selection.\", \"Name your Croc:\", \"Pick a color:\", \"Pick a breed:\"]'),(64,'pets','[\"catalog_pet_headline1_en\"]','[\"Good things come in small packages and Habbo\'s Terriers are no exception.\", \"Give a name:\", \"Pick a color:\", \"Pick a breed:\"]'),(65,'pets','[\"catalog_pet_headline1_en\"]','[\"These little scamps were destined for the dining table until we struck a deal with a local farmer to rescue their cute pigtails! Adopt your little piglet today, all you need now is a name.\", \"Give a name:\", \"Pick a color:\", \"Pick a breed:\"]'),(66,'pets','[\"catalog_pet_headline1_en\"]','[\"A large, heavy, mammal that walks on the soles of its feet, with thick fur and a very short tail. Fall in love with our adorable range of Bears that include the Grizzly and Polar varieties!\", \"Give a name:\", \"Pick a color:\", \"Pick a breed:\"]'),(67,'default_3x3','[\"catalog_pet_headline2\", \"ctlg_pet_teaser1\", \"catalog_special_txtbg2\"]','[\"Keep your Pet happy and healthy. Feed it to keep strong but don\'t forget about exercise! Please note, no fish are hurt in the feeding of your Pet.\", \"\", \"You gotta keep \'em happy\"]'),(68,'pets2','[\"catalog_pet_headline1_en\", \"ctlg_pet_note\"]','[\"Pets are inhabitants of Habbo Hotel too, so each pet owner needs to know a bit about them. Look after your pet by looking through our key points below.\", \"Few things you should know:\", \"- You cannot trade or give away pets. Once you purchase them, they will be yours forever.\\r\\n- You can own as many as you want, but you can have no more than 5 pets per room.\\r\\n- You can take pets with you to other rooms, should the room owner allow you to do so.\\r\\n- Your pet needs to be trained before it\'ll listen to your commands. By training your pets, you can gain some awesome achievements as well.\", \"\"]'),(71,'default_3x3','[\"catalog_header_hc\", \"catalog_hc_teaser\", \"\"]','[\"Habbo Club is our VIP members-only club - absolutely no riff-raff admitted! Members enjoy a wide range of benefits, including exclusive clothes, free gifts and an extended friends list\", \"\", \"\"]'),(72,'club_gifts','[\"catalog_header_hc\"]','[]'),(73,'default_3x3','[\"hc2_clubtitle\", \"catalog_hc_teaser\", \"catalog_special_txtbg1\"]','[\"NEW Habbo Club Furni range. Allow these elegant delights to make your room sophisticated and humble. They look great placed with your monthly gifts!\", \"Click on an item to see more details\", \"For Habbo Club members only!\"]'),(91,'default_3x3','[\"header_studio\", \"catalog_limited_teaser1_001\", \"\"]','[\"This furniture is for internal use only.\", \"Click on the item you want for more information\", \"\"]'),(92,'default_3x3','[\"header_studio\", \"catalog_limited_teaser1_001\", \"\"]','[\"These miscellaneous items do not fit a specific category within the Catalogue, or they are meant for a different purpose.\", \"Click on the item you want for more information\", \"\"]'),(93,'trophies','[\"catalog_trophies_headline1_ca\"]','[\"The trophies in this page are for Staff members to give away or as prize in competitions.\"]'),(94,'default_3x3','[\"catalog_rares_headline1\", \"catalog_xma_teaser3_en\"]','[\"These Rares are for internal use only.\"]'),(95,'default_3x3','[\"catalog_cltbs_header1_en\", \"catalog_cltbs_teaser_en\"]','[\"These Rares are for internal use only.\"]'),(101,'marketplace_own_items','[\"catalog_marketplace_header_en\"]','[\"\"]'),(102,'marketplace','[\"catalog_marketplace_header_en\"]','[\"\"]'),(103,'recycler_info','[\"catalog_marketplace_header_en\", \"catalog_note_marketplace\"]','[\"The Habbo Marketplace is a convenient and safe way to buy and sell items in Habbo.\", \"How does the Marketplace work?\", \"Selling items:\\r\\nYou can sell any item which is tradable by selecting the item in your inventory and clicking on \\\"Sell in Marketplace\\\". You are able to post 5 items for sale at the cost of 1 credit.\\r\\n\\r\\nBuying items:\\r\\nBrowse for the item you want to buy on the Marketplace Offers page and click Buy. We guarantee you\'ll get the item at the cheapest price available at the moment of purchase.\", \"\"]'),(201,'default_3x3','[\"catalog_extra_headline1\", \"catalog_extra_teaser1\", \"catalog_special_txtbg2\"]','[\"However you place your essential furniture, it\'s the finishing touches that express your true personality. And don\'t forget, like everything else, these accessories can be moved about to suit your mood.\", \"Click on an item for more information\", \"I love my rabbit...\"]'),(202,'default_3x3','[\"catalog_alh_headline2\", \"catalog_alh_teaser2\", \"catalog_special_txtbg2\"]','[\"Trade the everyday for a taste of the exotic. Carved screens, glowing lanterns and intricate tilework turn any room into a palace straight out of Arabian nights.\", \"Click on an item for more information\", \"Fit for a sultan!\"]'),(203,'default_3x3','[\"catalog_arc_header1_en\", \"catalog_arc_teaser1_en\"]','[\"Stay cool (or warm with out campfire!) with and create your own Winter Wonderland or Humble Homeland for your Penguins.\", \"Click on the item you want for more information\", \"\"]'),(204,'default_3x3','[\"catalog_area_headline1\", \"catalog_area_teaser1\", \"catalog_special_txtbg2\"]','[\"Clean, chunky lines set this collection apart as a preserve of the down-to-earth Habbo. It\'s beautiful in its simplicity, and welcoming to everyone.\", \"Click on the item you want for more information.\", \"Beautiful in its simplicity!\"]'),(205,'default_3x3','[\"catalog_asian_headline1\", \"catalog_asian_teaser1\"]','[\"Bring a little balance to your room with this handcrafted collection inspired by ancient Eastern traditions. With a touch of Yin and Yang and a dash of Feng Shui, this furni feels right at home in any Habbo interior.\", \"Click on the item you want for more information\", \"\"]'),(206,'default_3x3','[\"catalog_bath_headline1\", \"catalog_bath_teaser1\", \"catalog_special_txtbg2\"]','[\"Have some fun with the cheerful bathroom collection. Give yourself and your guests somewhere to freshen up - vital if you want to avoid nasty niffs. Might be an idea to put your loo in a corner though...\", \"Click on an item for more information.\", \"Every Habbo needs one!\"]'),(207,'default_3x3','[\"catalog_lc_headline2_en\", \"catalog_lc_teaser1_en_001\"]','[\"Our second World is Mythology. Check this Furni to find out what we\'re doing in this mystical land of wonder...\", \"Click an item for more details.\"]'),(208,'default_3x3','[\"catalog_header_bling_en\", \"bling_teaser\"]','[\"Bling things up with some serious glitz and glamour! We hope you brought your lucky charm, cause you might just need it...\"]'),(209,'default_3x3','[\"catalog_candy_headline1\", \"catalog_candy_teaser1\", \"catalog_special_txtbg2\"]','[\"Candy combines the coool, clean lines of the Mode collection with a softer, more soothing style. It\'s urban sharpness with a hint of the feminine.\", \"Click an item for more info.\", \"Relax! It\'s faux-fur.\"]'),(210,'default_3x3','[\"country_header1_en_001\", \"country_teaser1_en\"]','[\"Old McHabbo had a farm... and now you will have everything you need to create the perfect rural retreat away from the hustle and bustle of your city slicker life!\", \"Click on an item for more information.\"]'),(211,'default_3x3','[\"catalog_diner_header_en\", \"catalog_diner_teaser2_en\"]','[\"Step into 1950s America with the bright and colourful Diner Range. Check back daily for the latest specialty dish.\"]'),(212,'default_3x3','[\"catalog_easter_headline1\", \"catalog_easter_teaser1\", \"catalog_special_txtbg2\"]','[\"\'Egg\'cellent furni - Bouncing bunnies, fluffy chicks, choccy eggs... Yep, it\'s Easter! Celebrate with something \'eggstra\' special from our Easter range. But hurry - it\'s not here for long this year!\", \"Click on an item for more details.\", \"\'Egg\'-Tastic!\"]'),(213,'default_3x3','[\"catalog_exe_headline1_en\", \"catalog_exe_teaser_en\"]','[\"For the ultimate business man, the Executive range with its leather seats and Italian coffee is a dream! How about you try the easy lifestyle?\", \"Click on an item for more information.\"]'),(214,'default_3x3','[\"catalog_flags_headline1\", \"catalog_flags_teaser1\", \"catalog_special_txtbg2\"]','[\"If you\'re feeling patriotic, get a flag to prove it. Our finest cloth flags will brighten up the dullest walls.\", \"Click on the item you want for more information.\", \"Flag this section for later!\"]'),(215,'default_3x3','[\"catalog_gallery_headline1\", \"catalog_posters_teaser1\", \"catalog_special_txtbg2\"]','[\"Adorn your walls with wondrous works of art, posters, plaques and wall hangings. The Gallery is bursting with items to suit all tastes, from kitsch to cool, traditional to modern.\", \"Click on the item for more information.\", \"Brighten up your walls!\"]'),(216,'default_3x3','[\"catalog_gls_headline1_en\", \"catalog_gls_teaser1_fi\"]','[\"Clear style, colourful choices! This Furni range is made from plexiglass and comes in a variety of colours. Mix and match your favourites to create a modern lounge.\", \"Click on an item for more information.\"]'),(217,'default_3x3','[\"catalog_gothic_headline1\", \"catalog_gothic_teaser1\"]','[\"What lurks beneath the still, dark surface? Create your own underworld with these Haunted classics.\", \"Click on an item for more details.\"]'),(218,'default_3x3','[\"greel_header\", \"greek_catateaser\"]','[\"Let the games begin! Build an Olympic arena or a temple for the gods with this furni range inspired by ancient Greece.\"]'),(219,'default_3x3','[\"catalog_gru_headline1_en_001\", \"catalog_gru_teaser_en_001\"]','[\"Alternative Habbos with alternative style or rebellious students with a point to prove. The Grunge range will get your bedroom looking just the way you  like it - organized, neat and tidy!\"]'),(220,'default_3x3','[\"ctlg_habbowood_headline1_en\", \"cine_2011_teaser\"]','[\"Lights, camera, action! Get in the spotlight with perfect props and movie-making.\", \"Click on an item for more details.\"]'),(221,'default_3x3','[\"catalog_halloween_headline1_ca\", \"catalog_halloween_teaser\"]','[\"Get your bony hands on this creepy collection of ghoulish goodies and turn your room into a haunted hideout. Everything you need for a proper spookfest!\", \"Click on an item for more information.\"]'),(222,'default_3x3','[\"catalog_iced_headline1_ca\", \"catalog_iced_teaser1\", \"catalog_special_txtbg2\"]','[\"For the Habbo who needs no introduction. It\'s so chic, it says everything and nothing. It\'s a black canvas, let your imagination to run wild!\", \"Click on the item you want for more information\", \"These chairs are so comfy.\"]'),(223,'default_3x3','[\"catalog_jap_header1_no\", \"catalog_jap_teaser3_en\"]','[\"From sushi to tatami mats and katanas, bring a touch of Japan to your room! Create a peaceful tea house, deck out your dojo or open your own sushi bar with this stylish furniture.\", \"Click on an item for more details.\"]'),(224,'default_3x3','[\"kitchen_header_en\", \"kitchen_teaser_en\", \"catalog_special_txtbg2\"]','[\"The Hotel Kitchen has been identified as the cause of food poisoning epidemic. Piers is being trained up in food hygiene and we\'re giving you the change to join in with our fantastic, eagerly anticipated range of Kitchen Furni.\", \"Click an item for more info.\", \"Choccy mouse you say?\"]'),(225,'default_3x3','[\"catalog_lodge_headline1_uk\", \"catalog_lodge_teaser1\", \"catalog_special_txtbg2\"]','[\"For that ski-lodge effect - especially good by an open fire. The Lodge Collection is for Habbos who have a no-frills attitude to home furnishing and those who appreciate the beauty of wood.\", \"Click on an item for more information.\", \"How was your boarding today?\"]'),(226,'default_3x3','[\"LT_header_en_001\", \"LT_teaser_en\", \"catalog_special_txtbg2\"]','[\"The Lost Tribe has been found, but before you explore their world, it\'s time to decide which tribe you wish to join. Who will you pick? The Squidies, Birdies or Simians?\", \"Lost Tribe Furni out now!\", \"Tiki has returned, but with Lava?\"]'),(227,'default_3x3','[\"catalog_header_mad_scientist\", \"catalog_teaser_mad_scientist\"]','[\"Every mad scientist needs a lab! Strange potions, electric experiments and mysterious machines await in this mysterious collection. Build your own laboratory and see what you can bring to life!\"]'),(228,'default_3x3','[\"catalog_mode_headline1_uk\", \"catalog_mode_teaser1\", \"catalog_special_txtbg2\"]','[\"Steely, grey industrial standard metal with a sleek design. The perfect range for a streetwise city dweller.\", \"Click on an item for more information.\", \"So shiny and new.\"]'),(229,'default_3x3','[\"catalog_dimmers_header_en\", \"dimmers_teaser\"]','[\"Our range of Mood Lights allow you to spectacularly transform your room in just a click. What will your room look like today? Click the switch and find out now.\", \"Click on an item for more information.\"]'),(230,'default_3x3','[\"catalog_neon_header1_en\", \"catalog_neon_teaser1_en\"]','[\"Party animals rejoice! Feel the base and reach for the lasers with the Neon Furni range - everything you need to get the party started!\"]'),(231,'default_3x3','[\"organo_cata_header\", \"organo_teaser\", \"catalog_special_txtbg2\"]','[\"Add a touch of psychedelia to your room with Organo! Bold shapes and flowing curves give this modern furni range a style all its own.\", \"\", \"Am I tripping?\"]'),(232,'default_3x3','[\"catalog_plants_headline1_uk\", \"catalog_plants_teaser1\", \"catalog_special_txtbg1\"]','[\"Every room needs a plant! Not only do they bring a bit of the outside inside, they also enhance the air quality!\", \"Click on a plant to see more details.\", \"Ge-om-e-tree!\"]'),(233,'plasto','[\"catalog_plasto_headline1_uk\"]','[\"Can you feel that 1970s vibe? Decorate with Plasto and add some colour to your life. Choose a colour that reflects your mood, or just pick your favourite shade.\"]'),(234,'default_3x3','[\"FBP_header\", \"mall_teaser\"]','[\"Shops, cafés and spacious walkways - everything you need to create your own mall! Set up your storefronts and give Habbos a place to shop, meet and hang out.\"]'),(235,'default_3x3','[\"catalog_pura_headline1\", \"catalog_pura_teaser1\", \"catalog_special_txtbg2\"]','[\"The cleanest, freshest range. You can almost hear it breath cool and tranquility within your room. Use it to create a haven away from the hectic lifestyle of Habbo Hotel.\", \"Click on an item for more information.\", \"So many colors!\"]'),(236,'default_3x3','[\"rela_header_en\", \"rela_teaser_en\"]','[\"Set the mood with our Relax furni. Fill your room with scented candles, settle into a hanging chair and watch the flames flicker. Put your feet up and let your worries drift away!\"]'),(237,'default_3x3','[\"catalog_rom_headline1_en\", \"catalog_rom_teaser_en\"]','[\"The Romantique range features Grand Pianos, old antique lamps and tables. It is the ideal range for setting a warm and loving mood in your room. Spruce up your room and invite that special someone over.\", \"Click on the item you want for more information.\"]'),(238,'default_3x3','[\"catalog_rugs_headline1_uk\", \"catalog_rugs_teaser1\", \"catalog_special_txtbg2\"]','[\"We have rugs for all ocassions. All rugs are non-slip and washable.\", \"Click on the item you want for more information\", \"Rugs, rugs and more rugs!\"]'),(239,'default_3x3','[\"runway_header_en\", \"runway_teaser_en\"]','[\"This Furni never goes out of style! Become a style icon, design your own collection or take the catwalk by storm. Have you got what it takes to be a Habbo Runway star?\"]'),(240,'default_3x3','[\"sf_header_en\", \"sf_teaser_en\"]','[\"Create the ultimate in space travel whether it be a galactic war or just a leisure lunar hangout.\", \"Click on an item to get more info.\"]'),(241,'default_3x3','[\"catalog_shal_header1_en\", \"catalog_shal_teaser_en\"]','[\"Set the scene for a Bollywood love story with Shalimar! Bright colours, lotus flowers and elephants will bring movie magic to your room. Add rose petals and let the music, dancing and romance begin!\", \"Click on an item for more details.\"]'),(242,'default_3x3','[\"catalog_sports_headline1_ca\", \"catalog_sports_teaser1\"]','[\"Feeling active? Get your sports gear here and burn those calories! From running tracks to basketball courts, we\'ve got everything you need to train, compete and host your own games.\", \"Click on an item for more details.\"]'),(243,'default_3x3','[\"Stars_header\", \"summer_teaser\"]','[\"Summertime! Habbos are heading for beautiful destinations to enjoy the sun, sea and sand. Build your own beach resort and throw the best summer parties in Habbo!\", \"Click on the item you want for more information\", \"\"]'),(244,'default_3x3','[\"catalog_doors_headline1\", \"catalog_teleports_teaser2_001\", \"\"]','[\"Beam yourself from one room to another with our space age teleports. Buy a pair, put one in each room, and you\'ve got your own suite! Teleports are sold in pairs (obviously!), so if you trade for them, check that you\'re getting a linked pair.\", \"Click on an item for more information.\", \"\"]'),(245,'default_3x3','[\"catalog_tiki_header1_en\", \"catalog_tiki_teaser1_en\"]','[\"Whisk yourself away to a tropical paradise with Tiki furniture. The smooth wood tones and tropical brights make the perfect setting for a beach party.\"]'),(246,'trophies','[\"catalog_trophies_headline1_ca\"]','[\"Everyone\'s a winner! Reward all your friends with our fabulous glittering array of bronze, silver and gold trophies.\\r\\nFirst, choose the trophy model, the metal and then carefully type your inscription - it\'s permanent!.\\r\\nWe\'ll engrave the inscription along with your name and the date.\"]'),(247,'default_3x3','[\"urban_header_en\", \"urban_teaser_en\"]','[\"With its city-inspired style, Urban is perfect for any street, alleyway or road. Rubbish bins, street lights and benches - all the Urban furniture you need!\", \"Click on an item for more details.\"]'),(248,'default_3x3','[\"Valentines_header\", \"catalog_love_teaser1\"]','[\"It is Valentine\'s Day and time to express your love and affection for your friends. Go wild and leave anonymous Heart Stickies all over the hotel!\", \"Click on an item to see more details\"]'),(249,'default_3x3','[\"catalog_vir_header1_en\", \"catalog_vir_teaser_en\"]','[\"A virus is spreading through Habbo Hotel. Many casualties reported and it could get much worse! Whether you are hoping to get infected Habbos or look after number one, get your clean hands on our terrifying Infection Furni.\", \"Click on an item to see more details.\"]'),(250,'default_3x3','[\"ctlg_windows_headline1_en\", \"ctlg_windows_teaser1_en\", \"catalog_special_txtbg1\"]','[\"Let some sunshine in! Our windows come in many styles to give a unique look to your room. Who said your room does not have a view? It does now.\", \"Click on the item you want for more information\", \"Ooh, new view!\"]'),(251,'default_3x3','[\"catalog_xmas_headline2_en\", \"xmas2009_catalogue\"]','[\"Get yourself into the Christmas spirit and check out all the new items we\'ve prepared for you.\", \"Click on the item you want for more information\", \"\"]'),(252,'default_3x3','[\"flowerpower_header_en\", \"garden_teaser_en\"]','[\"The Hotel has been overrun by this botanical bonanza of greenery and color. With these newest shroomy additions, what will you build?\"]'),(253,'default_3x3','[\"catalog_roller_headline1\", \"catalog_teaser_rollers_en\"]','[\"Move your imagination, while you move your Habbo! Perfect for mazes, games, for keeping your queue moving or making your pet go round in circles for hours. Available in multi-packs - the more you buy, the cheaper the Roller!\", \"Click on a Roller for more information.\"]'),(254,'default_3x3','[\"catalog_twilight_header_en\", \"twi_teaser\"]','[\"The Twilight Saga - New Moon is here! To celebrate the arrival of the Cullens, some special furniture has been made so you can create your own Twilight rooms.\"]'),(255,'default_3x3','[\"catalog_header_AI1_en\", \"catalog_teaser_AI1_en\"]','[\"Create your own American Idol world in Habbo with this exclusive AI furniture set.\", \"Click on an item to see more details.\"]'),(257,'default_3x3','[\"catalog_spw_header2_es\", \"catalog_spw_teaser1_es\"]','[\"The Spiderwick Exhibition has arrived at the \\\"Museum of Invention\\\" in Habbo Hotel. Grab yourself a limited edition souvenir item of Furni below before it\'s too late!\"]');
