INSERT INTO `global_message_texts` VALUES ('action_too_fast','You\'re doing that too fast. Wait a moment and try again.'),('alert_sent','Alert sent to {username}.'),('badge_already_owned','{username} already has the badge {badge}.'),('badge_given','Gave {username} the badge {badge}.'),('ban_applied','{username} is banned {length}: {reason}'),('ban_length_for','for {duration}'),('ban_length_permanent','permanently'),('bots_reloaded','Bots reloaded. {bots} bot(s) in {rooms} loaded room(s).'),('choose_ban_length','Choose how long the ban should last.'),('currency_given','Gave {username} {amount} {currency}. They now have {balance}.'),('duration_days','{count} days'),('duration_hours','{count} hours'),('duration_minutes','{count} minutes'),('duration_one_day','1 day'),('duration_one_hour','1 hour'),('duration_one_minute','1 minute'),('furni_command_tip',' Tip: use the :furni command!'),('kick_cant_be_kicked','{username} can\'t be kicked.'),('kick_not_allowed','You can\'t kick anyone out of this room.'),('kick_not_here','{username} is not in this room.'),('logged_in_elsewhere','You have logged in somewhere else, so you have been disconnected here.'),('messenger_too_fast','You\'re sending messages too fast. Wait {seconds} seconds before sending another.'),('mood_light_one_per_room','You can only place one Mood Light per room. If you can\'t find the one you already placed, it is probably well-hidden.'),('motto_too_fast','You\'re changing your motto too fast - wait a moment and try again.'),('mute_applied','{username} is muted for {duration}.'),('name_change_every_days','once every {days} day(s)'),('name_change_every_hour','once an hour'),('name_change_summary','{changes} You can change it at most {every}.{wait}'),('name_change_wait',' You can change it again in {wait}.'),('name_changes_unlimited','You have changed your name {changes} time(s) and can change it as often as you like.'),('name_changes_used','You have used {used} of your {limit} name change(s) and have {left} left.'),('no_message','Write a message first.'),('no_such_user','There is no such user.'),('not_in_room','You are not in a room.'),('not_muted','{username} isn\'t muted.'),('pickall_owner_only','Only the room\'s owner can pick up all its furniture.'),('public_rooms_reloaded','Public rooms reloaded. {rooms} room(s) in {folders} categorie(s).'),('purchases_off_shutdown','The Hotel is shutting down - purchasing furniture and Habbo Club, and trading, are disabled.'),('rank_refusal_lower_only','You can\'t {verb} {username} as they are your same or higher rank than you.'),('rank_refusal_self','You can\'t {verb} {username}.'),('rank_refusal_yourself','You can\'t {verb} yourself.'),('roller_interval_many','{count} ticks'),('roller_interval_one','tick'),('roller_speed_current','Roller speed is {speed} (every {interval}). Use :roller_speed 1-4.'),('roller_speed_no_rights','You need rights in this room to change its roller speed.'),('roller_speed_set','Roller speed set to {speed} (every {interval}).'),('room_mute_applied','This room is muted for {duration}.'),('room_name_inappropriate','Inappropriate to Hotel Management.'),('room_not_muted','This room isn\'t muted.'),('room_unmute_applied','This room isn\'t muted any more.'),('shutdown_already','The hotel is already shutting down.'),('shutdown_bad_time','The time the hotel opens again is HH:mm. For example, :shutdown confirm 18:30.'),('shutdown_confirm_prompt','This closes the hotel in {minutes} minutes: trading, purchases, the recycler, the marketplace and pet training and feeding stop at once, nobody new can log in, and then everyone is disconnected and the emulator stops. Type :shutdown confirm [HH:mm] to do it.'),('softkick_not_allowed','You can\'t kick anyone in this room.'),('superban_applied','{username} is superbanned {length}: {reason}'),('teleport_bad_height','The height must be a number, for example, :teleport on 1.5'),('teleport_height_anywhere','on the topmost height of the tile'),('teleport_height_at','at height {height}'),('teleport_off','Teleport mode is off.'),('teleport_on','Teleport mode is on with height set to {height}.'),('teleport_status_off','Teleport mode is off. Use :teleport on [z] or :teleport off.'),('teleport_status_on','Teleport mode is on, {height}. Use :teleport on [z] or :teleport off.'),('trade_nothing_exchanged','The trade could not be completed, so nothing was exchanged.'),('unmute_applied','{username} can talk again.'),('usage_alert','Use :alert [user] [message].'),('usage_ban','Use :ban [user] [hours - at least 1] [reason].'),('usage_fx','Use :fx [id] - 0 takes it off.'),('usage_give_currency','Use :{command} [user] [amount] - amount above 0.'),('usage_givebadge','Use :givebadge [user] [code] - a code is at most {max} characters.'),('usage_handitem','Use :handitem [id] - 0 puts it down.'),('usage_kick','Use :kick [user].'),('usage_motto','Use :motto <new motto>.'),('usage_mute','Use :mute [user] [hours - at least 1].'),('usage_roller_speed','Use :roller_speed 1, 2, 3 or 4 (4 is the fastest).'),('usage_roomalert','Use :roomalert [message].'),('usage_roommute','Use :roommute [hours - at least 1].'),('usage_softkick','Use :softkick [user].'),('usage_start_vote','Use :start_vote [question].'),('usage_superban','Use :superban [user] [days - at least 1] [reason].'),('usage_teleport','Use :teleport on [z] or :teleport off.'),('usage_unmute','Use :unmute [user].'),('user_not_found','There is no user called {username}.'),('user_not_in_room','{username} isn\'t in a room.'),('user_not_online','{username} isn\'t online.'),('vote_already_going','This room already has a vote going. You can end it with :end_vote.'),('vote_just_ended','A vote has only just ended in this room - wait a moment.'),('vote_none','There is no vote going in this room.'),('vote_start_cooldown','You can start a vote once every {seconds} seconds.'),('you_are_muted','You are muted. Left: {duration}.');
