INSERT INTO `guide_bot_actions` VALUES (1,'on_arrival',NULL,'[[{\"to\": \"center\", \"type\": \"walk\"}, {\"type\": \"wait\", \"ticks\": 1}, {\"who\": \"owner\", \"type\": \"look_at\"}, {\"type\": \"wave\"}]]',0,'1'),(2,'do_at_random','{\"max_ticks\": 30, \"min_ticks\": 10}','[[{\"type\": \"walk\", \"max_distance\": 3}]]',0,'1'),(3,'user_chats','{\"match\": \"contains\", \"phrases\": [\"scam\"], \"cooldown_ticks\": 6}','[[{\"text\": \"Be careful\", \"type\": \"say\"}]]',0,'1'),(4,'user_chats','{\"match\": \"contains\", \"phrases\": [\"friends\"], \"cooldown_ticks\": 6}','[[{\"text\": \"Looking for people to hang out with?\", \"type\": \"say\"}, {\"type\": \"wait\", \"ticks\": 1}, {\"text\": \"Open the Navigator and see where everyone else is.\", \"type\": \"say\"}]]',0,'1'),(5,'user_chats','{\"match\": \"contains\", \"phrases\": [\"move\"], \"cooldown_ticks\": 6}','[[{\"text\": \"To move, click the floor on the spot you want to go to.\", \"type\": \"say\"}]]',0,'1'),(6,'user_chats','{\"match\": \"contains\", \"phrases\": [\"love\"], \"cooldown_ticks\": 6}','[[{\"text\": \"AI can\'t feel love! But you might find a real virtual connection in a dating room.\", \"type\": \"say\"}]]',0,'1'),(7,'user_chats','{\"match\": \"contains\", \"phrases\": [\"help\"], \"cooldown_ticks\": 6}','[[{\"text\": \"You can call for help if someone is giving you a hard time.\", \"type\": \"say\"}, {\"type\": \"wait\", \"ticks\": 1}, {\"text\": \"Just click on the yellow question mark icon.\", \"type\": \"say\"}]]',0,'1'),(8,'user_chats','{\"match\": \"contains\", \"phrases\": [\"wave\"], \"cooldown_ticks\": 6}','[[{\"type\": \"wave\"}, {\"type\": \"wait\", \"ticks\": 1}, {\"text\": \"If you feel like waving, click the face icon and click wave.\", \"type\": \"say\"}]]',0,'1'),(9,'user_chats','{\"match\": \"contains\", \"phrases\": [\"pets\"], \"cooldown_ticks\": 6}','[[{\"text\": \"Buy your furry friend from the catalogue.\", \"type\": \"say\"}, {\"type\": \"wait\", \"ticks\": 1}, {\"text\": \"He\'ll need food and toys to be happy and content and remember, a pet is for life, you cannot give it away!\", \"type\": \"say\"}]]',0,'1'),(10,'user_chats','{\"match\": \"contains\", \"phrases\": [\"ff\"], \"cooldown_ticks\": 6}','[[{\"text\": \"Participate in some games like falling furni.\", \"type\": \"say\"}, {\"type\": \"wait\", \"ticks\": 1}, {\"text\": \"The trick is to always stand one square away from other users.\", \"type\": \"say\"}, {\"type\": \"wait\", \"ticks\": 1}, {\"text\": \"When the owner drops a chair to the room, try to sit on it.\", \"type\": \"say\"}, {\"type\": \"wait\", \"ticks\": 1}, {\"text\": \"The one left out without a chair is losing. The one sitting in the chair at last is the winner.\", \"type\": \"say\"}, {\"type\": \"wait\", \"ticks\": 1}, {\"text\": \"Falling Furni games are marked as FF or Falling Furni.\", \"type\": \"say\"}]]',0,'1'),(11,'user_chats','{\"match\": \"contains\", \"phrases\": [\"dance\"], \"cooldown_ticks\": 6}','[[{\"type\": \"dance\", \"ticks\": 5}, {\"type\": \"walk\", \"max_distance\": 3}]]',0,'1'),(12,'user_chats','{\"match\": \"contains\", \"phrases\": [\"hi\"], \"cooldown_ticks\": 6}','[[{\"text\": \"Hiya!\", \"type\": \"say\"}]]',0,'1'),(13,'user_chats','{\"match\": \"contains\", \"phrases\": [\"kick\"], \"cooldown_ticks\": 6}','[[{\"text\": \"You can kick other users from your room if they are getting too bossy or give a hard time.\", \"type\": \"say\"}]]',0,'1'),(14,'user_chats','{\"match\": \"contains\", \"phrases\": [\"shout\"], \"cooldown_ticks\": 6}','[[{\"text\": \"Shouting is not recommended. Make sure you stand quite close to the people you want to chat with.\", \"type\": \"say\"}]]',0,'1');
