INSERT INTO `room_bots` VALUES (1,55,NULL,'Harry','M','ch-809-62.hd-180-1.sh-300-64.lg-285-64.hr-831-45','Welcome to Habbo Hotel!',8,19,0.0000,2,'[[8, 16, 9, 22]]','0','2026-10-17 20:59:35'),(2,153,NULL,'Marcel','M','sh-300-110.hd-180-1.hr-829-39.lg-285-110.ch-245-110','Step into a world of reading!',10,15,1.0000,2,'[[9, 14, 11, 16]]','0','2026-10-19 01:15:14');
INSERT INTO `room_bots_actions` VALUES (1,1,'do_at_random',NULL,'[{\"text\": \"Please keep it down, people are trying to think!\", \"type\": \"say\"}, {\"text\": \"Only use the Call for help in an emergency!\", \"type\": \"say\"}, {\"text\": \"Want to know more about Habbo Hotel? Ask a Habbo Guide!\", \"type\": \"say\"}, {\"text\": \"Is it me or is something BIG about to happen?\", \"type\": \"say\"}, {\"text\": \"In Trouble? Call for Moderator assistance using the Yellow Question Mark!\", \"type\": \"say\"}, {\"text\": \"There\'s no such thing as a free lunch or free credits!\", \"type\": \"say\"}]',0,'1'),(2,1,'user_says','{\"match\": \"exact\", \"phrases\": [\"hello harry\", \"hi harry\"], \"case_sensitive\": false}','[{\"text\": \"Why Hello there! *Shakes Habbo Hand* My name\'s Harry.\", \"type\": \"say\"}, {\"text\": \"Hello, Hello, Hello!\", \"type\": \"say\"}, {\"text\": \"Hello and welcome to Habbo Hotel! Enjoy your stay! :)\", \"type\": \"say\"}]',0,'1'),(3,1,'do_at_random','{\"max_ticks\": 60, \"min_ticks\": 20}','[{\"type\": \"walk\"}]',0,'1'),(4,2,'do_at_random',NULL,'[{\"text\": \"Better to remain silent and be thought a fool than to speak and remove all doubt.\", \"type\": \"say\"}, {\"text\": \"In this room, we keep quiet. Learning takes diligence.\", \"type\": \"say\"}, {\"text\": \"Can I be helping any Habbo?\", \"type\": \"say\"}, {\"text\": \"English is the tongue of Shakespeare\", \"type\": \"say\"}, {\"text\": \"Not to be absolutely certain is, I think, one of the essential things in rationality.\", \"type\": \"say\"}, {\"text\": \"If one does understand a person, one tends to regard him as a fool.\", \"type\": \"say\"}, {\"text\": \"I miss fresh bread daily\", \"type\": \"say\"}, {\"text\": \"With an onion and a tomato, every meal is a feast\", \"type\": \"say\"}]',0,'1'),(5,2,'do_at_random','{\"max_ticks\": 60, \"min_ticks\": 20}','[{\"type\": \"walk\"}]',0,'1'),(6,2,'user_says','{\"match\": \"contains\", \"phrases\": [\"book\", \"1 book\", \"one book\", \"books\"], \"case_sensitive\": false}','[{\"text\": \"Ah, so you want a book.\", \"type\": \"say\"}, {\"text\": \"Ah, I see you\'re a total bookworm.\", \"type\": \"say\"}, {\"text\": \"Have those books back by the weekend!\", \"type\": \"say\"}]',3,'1'),(7,2,'user_says','{\"match\": \"contains\", \"phrases\": [\"hello\", \"hi everyone\"], \"case_sensitive\": false}','[{\"text\": \"Welcome, and step into literary paradise.\", \"type\": \"say\"}, {\"text\": \"Hi buddy, all good?\", \"type\": \"say\"}, {\"text\": \"Greetings.\", \"type\": \"say\"}]',0,'1'),(8,2,'user_says','{\"match\": \"contains\", \"phrases\": [\"marcel\", \"uhh\", \"yow\", \"i think\", \"can i\"], \"case_sensitive\": false}','[{\"text\": \"Is that so?\", \"type\": \"say\"}, {\"text\": \"Whaddayamean?\", \"type\": \"say\"}, {\"text\": \"Easy you ruffians. I got only two hands and I work full-time.\", \"type\": \"say\"}, {\"text\": \"Yes, what would you like?\", \"type\": \"say\"}]',4,'1'),(9,2,'user_says','{\"match\": \"contains\", \"phrases\": [\"bobba\"], \"case_sensitive\": false}','[{\"text\": \"Turn your Bobba filter on and bad words are gone!\", \"type\": \"say\"}]',0,'1');

